import os


class Config:
    """
    Global configuration for the Heterogeneous Ensemble Strategy (XGBoost + LightGBM).
    """

    # --- General Configuration ---
    SEED = 42
    NUM_WORKERS = 12  # Based on available vCPUs

    # --- Paths ---
    # Input Directories (Read-Only)
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Data Paths (Generated by metadata script)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Directories
    WORKING_DIR = "./working"
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_3")  # For caching processed data
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Configuration ---
    TARGET_COL = "Cover_Type"
    ID_COL = "Id"
    # Note: Cover_Type classes are integers.
    # The models will likely require 0-indexed labels, which will be handled in the pipeline.

    # --- Feature Engineering ---
    # Interaction features to be explicitly created
    INTERACTION_FEATURES = ["Euclidean_Distance_To_Hydrology", "Hydrology_Elevation"]

    # --- Model Configuration: XGBoost ---
    # Strategy: Level-wise tree growth, high capacity, GPU accelerated
    XGB_PARAMS = {
        "booster": "gbtree",
        "objective": "multi:softprob",
        "eval_metric": "mlogloss",
        "tree_method": "hist",
        "device": "cuda",
        "max_depth": 10,
        "eta": 0.05,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "random_state": SEED,
        "n_jobs": NUM_WORKERS,
        "verbosity": 0,
    }

    # Training loop parameters for XGBoost
    XGB_FIT_PARAMS = {
        "num_boost_round": 5000,
        "early_stopping_rounds": 50,
        "verbose_eval": 100,
    }

    @classmethod
    def make_dirs(cls):
        """Creates necessary output directories."""
        os.makedirs(cls.IDEA_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
